package com.aistock.gateway;
import com.aistock.common.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.http.ResponseEntity;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ComparisonAiProxyTest {
 @Test void exactRoutesAndDedicatedTimeout()throws Exception{var client=mock(ComparisonAiPublicClient.class);when(client.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok("{}".getBytes()));var mvc=MockMvcBuilders.standaloneSetup(new ComparisonAiApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v1/comparison-explanations").param("comparisonId","11111111-1111-4111-8111-111111111111").header("X-User-Id","forged")).andExpect(status().isOk());verify(client).get(eq("comparison-explanations"),anyMap(),argThat(h->!h.containsKey("X-User-Id")));mvc.perform(get("/api/v1/comparison-explanations").param("owner","forged")).andExpect(status().isUnprocessableEntity());mvc.perform(post("/api/v1/comparison-explanations").content("x".repeat(513))).andExpect(status().isPayloadTooLarge());mvc.perform(post("/api/v1/comparison-explanations/operations/11111111-1111-4111-8111-111111111111")).andExpect(status().isNotFound());var config=new ComparisonAiClientConfiguration();assertEquals(65000,config.comparisonAiOptions().readTimeoutMillis());assertFalse(config.comparisonAiOptions().isFollowRedirects());assertSame(feign.Retryer.NEVER_RETRY,config.comparisonAiRetryer());assertEquals(30000,new ComparisonClientConfiguration().comparisonOptions().readTimeoutMillis());}

 @Test void preservesAllowlistedControlled503ButHidesUnexpectedFailures()throws Exception{for(String code:List.of("AI_BUSY","AI_NOT_CONFIGURED","AI_RESULT_UNCONFIRMED","UNEXPECTED_INTERNAL")){var client=mock(ComparisonAiPublicClient.class);var response=feign.Response.builder().status(503).reason("unavailable").headers(Map.of()).request(feign.Request.create(feign.Request.HttpMethod.POST,"http://private-host",Map.of(),new byte[0],java.nio.charset.StandardCharsets.UTF_8,null)).body(new ObjectMapper().writeValueAsString(Map.of("code",code,"message","private-host secret","data",com.fasterxml.jackson.databind.node.NullNode.instance)),java.nio.charset.StandardCharsets.UTF_8).build();when(client.post(anyString(),anyMap(),any())).thenThrow(feign.FeignException.errorStatus("comparison-ai",response));var mvc=MockMvcBuilders.standaloneSetup(new ComparisonAiApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();var result=mvc.perform(post("/api/v1/comparison-explanations").content("{}")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value(code.equals("UNEXPECTED_INTERNAL")?"COMPARISON_AI_SERVICE_UNAVAILABLE":code)).andReturn();assertFalse(result.getResponse().getContentAsString().contains("private-host"));}}
}
